Here is a Python code snippet that uses the `requests` library to send a payment request to the `/api/v3/send-payment` endpoint:

```python
import requests

def send_payment(amount):
    url = 'https://example.com/api/v3/send-payment'
    headers = {
        'Content-Type': 'application/json',
    }
    data = {
        'amount': amount,
    }

    try:
        response = requests.post(url, headers=headers, json=data)
        if response.status_code == 200:
            print("Payment sent successfully")
        else:
            print(f"Failed to send payment. Status code: {response.status_code}")
    except requests.exceptions.RequestException as e:
        print(f"Request failed with error: {e}")

# Replace 'https://example.com/api/v3/send-payment' with your actual endpoint URL
send_payment(1000)
```

